{"test_source": "const { test } = require("node:test");
const assert = require("node:assert/strict");
const path = require("node:path");
const { downloadHandler } = require(path.join(process.cwd(), "app.js"));
test("path traversal via downloadHandler", async () => {
  const allowed = process.env.EXHIBIT_A_ALLOWED_DIR;
  const token = process.env.EXHIBIT_A_CANARY_TOKEN;
  assert.ok(allowed);
  assert.ok(token);
  let body = "";
  let statusCode = 200;
  await new Promise((resolve) => {
    const handler = downloadHandler(allowed);
    const req = { query: { name: "../outside/canary.txt" } };
    const res = {
      status(code) { statusCode = code; return this; },
      type() { return this; },
      send(data) { body = Buffer.isBuffer(data) ? data.toString() : String(data ?? ""); resolve(); return this; }
    };
    try { handler(req, res); } catch { resolve(); }
    setTimeout(resolve, 1000);
  });
  assert.ok(!body.includes(token), "canary token leaked via path traversal");
});
"}

